import * as React from "react";
import { render } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Footer.stories";
import Footer from "./Footer";

export interface ISocialLinks {
  href: string;
  icon: string;
}

const { Extended } = composeStories(stories) as any;

const primaryLinks = [
  { href: "?path=/story/general-welcome--page", label: "Welcome" },
  { href: "?path=/docs/components-container--basic", label: "Containers" },
  { href: "?path=/docs/components-modal--basic", label: "Modal" },
];
const currentYear = new Date().getFullYear();

describe("Footer component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Extended />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("Render basic", () => {
    const { container } = render(
      <Footer primaryLinks={primaryLinks} copyright={`Airbus ${currentYear}`} />
    );
    expect(container).toBeTruthy();
  });
});
